head.script:
// https://inswave01.atlassian.net/browse/WAEA-1217
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
};



// 세 옵션 외의 차트 설정은 모든 버튼이 동일하게 고정 전달한다.
//  차트가 화면에 보이는 크기로 삽입되도록 삽입 위치를 주고, 항목 / 계열 / 데이터 범위를 지정한다.
scwin.runCase = function (vValue, strFileName, strShow) {
    target1.advancedExcelDownload({
        "fileName" : strFileName,
        "extension" : "xlsx",
        "sheetName" : "mysheet",
        "chart" : {
            "chartName" : "bar",
            "title" : "Region Value",
            "startRowIndex" : 9,
            "startColIndex" : 6,
            "endRowIndex" : 30,
            "endColIndex" : 12,
            "catGridLines" : vValue,
            "serGridLines" : vValue,
            "legend" : vValue,
            "catAxisRange" : { "startRowIndex" : 0, "startColIndex" : 1, "endRowIndex" : 0, "endColIndex" : 4 },
            "serAxisRange" : { "startRowIndex" : 1, "startColIndex" : 0, "endRowIndex" : 6, "endColIndex" : 4 },
            "dataAxisRange" : { "startRowIndex" : 1, "startColIndex" : 1, "endRowIndex" : 6, "endColIndex" : 4 }
        }
    });

    scwin.setReturnValue(strShow);
    scwin.setReturnValue("파일명 : " + strFileName + ".xlsx");
    scwin.setReturnValue("");
};



// [A] 가이드 타입(Boolean) 그대로 false 를 전달한다.
scwin.btn_boolFalse_onclick = function () {
    scwin.runCase(false, "chart_bool_false", "[A] catGridLines / serGridLines / legend = false (Boolean)");
};



// [B] 같은 세 옵션에 Boolean true 를 전달한다. (표시되는 상태의 대조군)
scwin.btn_boolTrue_onclick = function () {
    scwin.runCase(true, "chart_bool_true", "[B] catGridLines / serGridLines / legend = true (Boolean)");
};



// [C] 같은 세 옵션에 문자열 "false" 를 전달한다. (참고 대조)
scwin.btn_strFalse_onclick = function () {
    scwin.runCase("false", "chart_str_false", "[C] catGridLines / serGridLines / legend = 'false' (문자열)");
};
